('0387e0f7-fc66-599c-aa54-026bb20200ef','0055bac4-ae41-5124-86cf-a3cb91b411d1',1,'noun','A2',null,'W3',null,'[{"phrase":"on the understanding that","register":null,"definition_en":"if you agree to something on the understanding that something else will be done, you agree to it, believing that it will be done","translation":"اگر با چیزی موافق باشید که کار دیگری انجام خواهد شد، با این باور که انجام خواهد شد، با آن موافقت می کنید.","example":"Jack lent Sarah the money on the understanding that she would pay it back next month.","example_translation":"جک این پول را به سارا قرض داد که او ماه آینده آن را پس خواهد داد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001587865.mp3"}]'::jsonb),
