('14f1934d-9949-5427-b7f7-243993258d04','cb8a359d-2a55-588a-a99c-ce96bb434f26',1,'amount used','مقدار استفاده شده','spoken & written','the amount of energy , oil , electricity etc that is used',null,null,'مصرف، به‌کارگیری؛ استفاده (از خوراک، انرژی)','{}'::text[],'{}'::text[],array['high/low People should stop using expensive cars with a high petrol consumption.','total consumption Total consumption of petrol has risen by 20%.','domestic consumption (= use of something in the country where it is produced ) Domestic consumption of oil has increased.','household consumption (= use in the home ) The government is encouraging us to reduce our household consumption of water.','energy consumption Over a quarter of our energy consumption is in the home.','fuel/electricity/gas consumption There are three possible methods of reducing oil consumption.','reduce consumption The system will be introduced into all stores to reduce energy consumption by up to 10%','cut consumption (= reduce it ) a plan to cut energy consumption by 40%','consumption rises/increases/goes up Consumption of unleaded fuel rose by 17% in 1992.','consumption falls/decreases/goes down Coal consumption has fallen dramatically.']::text[],'[{"sentence":"dramatic rises in fuel consumption","translation":"افزایش چشمگیر مصرف سوخت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001106763.mp3"},{"sentence":"Vigorous exercise increases oxygen consumption.","translation":"ورزش شدید باعث افزایش مصرف اکسیژن می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001685736.mp3"}]'::jsonb,2),
('c236652c-4357-53a3-bdfe-54189d3ce15c','cb8a359d-2a55-588a-a99c-ce96bb434f26',2,'food/drink','غذا/نوشیدنی','formal','the act of eating or drinking',null,null,'عمل خوردن یا آشامیدن','{}'::text[],'{}'::text[],array['high/low People should stop using expensive cars with a high petrol consumption.','total consumption Total consumption of petrol has risen by 20%.','domestic consumption (= use of something in the country where it is produced ) Domestic consumption of oil has increased.','household consumption (= use in the home ) The government is encouraging us to reduce our household consumption of water.','energy consumption Over a quarter of our energy consumption is in the home.','fuel/electricity/gas consumption There are three possible methods of reducing oil consumption.','reduce consumption The system will be introduced into all stores to reduce energy consumption by up to 10%','cut consumption (= reduce it ) a plan to cut energy consumption by 40%','consumption rises/increases/goes up Consumption of unleaded fuel rose by 17% in 1992.','consumption falls/decreases/goes down Coal consumption has fallen dramatically.']::text[],'[{"sentence":"The consumption of alcohol on the premises is forbidden.","translation":"مصرف مشروبات الکلی در محل ممنوع است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001685743.mp3"},{"sentence":"The meat was declared unfit for human consumption.","translation":"این گوشت برای مصرف انسان نامناسب اعلام شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000549492.mp3"},{"sentence":"The Government wants to reduce tobacco consumption by 40%.","translation":"دولت می خواهد مصرف دخانیات را تا 40 درصد کاهش دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001685751.mp3"}]'::jsonb,3),
('c22d43b9-c871-52be-903f-157e21ad6201','cb8a359d-2a55-588a-a99c-ce96bb434f26',3,'buying','خرید','spoken & written','the act of buying and using products',null,null,'عمل خرید و استفاده از محصولات','{}'::text[],'{}'::text[],array['high/low People should stop using expensive cars with a high petrol consumption.','total consumption Total consumption of petrol has risen by 20%.','domestic consumption (= use of something in the country where it is produced ) Domestic consumption of oil has increased.','household consumption (= use in the home ) The government is encouraging us to reduce our household consumption of water.','energy consumption Over a quarter of our energy consumption is in the home.','fuel/electricity/gas consumption There are three possible methods of reducing oil consumption.','reduce consumption The system will be introduced into all stores to reduce energy consumption by up to 10%','cut consumption (= reduce it ) a plan to cut energy consumption by 40%','consumption rises/increases/goes up Consumption of unleaded fuel rose by 17% in 1992.','consumption falls/decreases/goes down Coal consumption has fallen dramatically.']::text[],'[{"sentence":"art intended for mass consumption (= to be bought, seen etc by lots of people )","translation":"هنری که برای مصرف انبوه در نظر گرفته شده است (= خرید، دیدن و غیره توسط افراد زیادی)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001685753.mp3"},{"sentence":"China’s austerity program has cut domestic consumption (= when products are bought in the country where they were produced ) .","translation":"برنامه ریاضت اقتصادی چین مصرف داخلی را کاهش داده است (= زمانی که محصولات در کشوری که تولید شده اند خریداری می شوند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001685757.mp3"}]'::jsonb,2),
