('b5bbef08-4c9e-5d96-867f-c781f7c84542','207a3d01-2b32-56eb-9ef8-c539bc9d2129',5,'improvement','بهبود','spoken & written','a change that makes a product, plan, idea etc better','[ countable ]',null,'تغییری که محصول، طرح، ایده و غیره را بهتر می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There have been significant computer developments during the last decade.","translation":"در دهه گذشته پیشرفت های قابل توجهی در رایانه صورت گرفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000821870.mp3"}]'::jsonb,1),
