('9fce10d7-7ce2-5f40-9d43-77c3ffeb438c','c907f6ed-585a-5814-8ab2-f38b715a122c',1,null,null,'spoken & written','to recognize and understand the difference between two or more things or people','[ intransitive, transitive ]',null,'تمایز قائل شدن، تشخیص دادن؛ متمایز ساختن',array['differentiate']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"His attorney argued that Cope could not distinguish between right and wrong.","translation":"وکیل او استدلال کرد که کوپ نمی تواند درست و غلط را تشخیص دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001147735.mp3"},{"sentence":"a method of distinguishing cancer cells from normal tissue","translation":"روشی برای تشخیص سلول های سرطانی از بافت طبیعی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690616.mp3"},{"sentence":"He can’t tell the difference between right and wrong.","translation":"او نمی تواند تفاوت بین درست و غلط را تشخیص دهد.","audio_url":null},{"sentence":"How do you tell cancer cells from healthy cells?","translation":"چگونه می توان سلول های سرطانی را از سلول های سالم تشخیص داد؟","audio_url":null}]'::jsonb,4),
