('36f77ca8-4648-5ae9-b48e-aac86afee62c','d2901573-bb04-5e3a-a662-aae57d9e869a',1,null,null,'spoken & written','without delay',null,null,'بلافاصله، فوراً؛ مستقیماً (پیش از آن)',array['at once']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Mix in the remaining ingredients and serve immediately.","translation":"بقیه مواد را با هم مخلوط کرده و بلافاصله سرو کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001403412.mp3"},{"sentence":"The telephone rang, and he answered it immediately.","translation":"تلفن زنگ خورد و او بلافاصله جواب داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001403413.mp3"},{"sentence":"Yes, I’ll do it right away .","translation":"بله، فورا این کار را انجام خواهم داد.","audio_url":null}]'::jsonb,3),
('c44cdd66-1351-5284-a059-2c554c976c21','d2901573-bb04-5e3a-a662-aae57d9e869a',2,null,null,'spoken & written','very soon before or after something',null,null,'خیلی زود قبل یا بعد از چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He retired immediately after the end of the war.","translation":"بلافاصله پس از پایان جنگ بازنشسته شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001719206.mp3"},{"sentence":"I can’t remember what happened immediately before the crash.","translation":"نمی توانم به یاد بیاورم که بلافاصله قبل از سقوط چه اتفاقی افتاد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001719209.mp3"}]'::jsonb,2),
('1900fbfd-4098-5381-a4a8-43ff406b163c','d2901573-bb04-5e3a-a662-aae57d9e869a',3,null,null,'spoken & written',null,null,'immediately obvious/apparent','بلافاصله، فوراً؛ مستقیماً (پیش از آن)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('21fc43f3-65e2-51f4-bb92-f343603a9875','d2901573-bb04-5e3a-a662-aae57d9e869a',4,null,null,'spoken & written','very near to something','[ +adj/adverb ]',null,'خیلی نزدیک به چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the seat immediately behind the driver","translation":"صندلی بلافاصله پشت راننده","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001719217.mp3"}]'::jsonb,1),
('e8ca6b22-4e55-5a47-a488-8136a3e080c4','d2901573-bb04-5e3a-a662-aae57d9e869a',5,null,null,'spoken & written',null,null,'immediately involved/affected/concerned etc','بلافاصله، فوراً؛ مستقیماً (پیش از آن)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('0bdaf819-4b4d-5600-b101-8b989d5c768a','4c1c52ef-0df3-5701-8cb1-6d2c03b64cf4',1,null,null,'spoken & written','as soon as',null,null,'به محض','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Immediately you begin to speak, he gives you his full attention.","translation":"بلافاصله شروع به صحبت می کنید، او تمام توجه خود را به شما معطوف می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001403439.mp3"}]'::jsonb,1),
('3afe6f29-7dce-581b-b05c-632d46b6941d','38b25d80-8c97-51b9-ba7e-4089ea8a62e6',1,null,null,'spoken & written','a possible future effect or result of an action, event, decision etc','[ countable usually plural ]',null,'پیامد، نتیجه ضمنی؛ معنا (درون)','{}'::text[],'{}'::text[],array['important/serious implications The results of the experiment could have important implications for scientists.','major implications (= very important or serious ) The lack of affordable housing has major implications for families living in rural areas.','profound implications (= extremely important or serious ) The transformation of Europe has profound implications for the defence industries.','far-reaching implications (= causing things to change in an important way ) The cuts in social security benefits had far-reaching implications for ethnic minorities.','the wider implications (= affecting more people or society in general ) What are the wider implications of this change in the law?','the full implications (= all the different effects ) The full implications of the decision will become clear over the next few weeks.','possible implications We discussed the possible implications of oil price rises.','practical implications Academic research often has practical implications.','financial implications Managers must be aware of the financial implications of their decisions.','political implications The court’s decision could have far-reaching political implications.','legal implications We have taken advice on the legal implications of our activities.','social implications She’s studying the social implications of different patterns of work.','have implications This is an environmental disaster which will have implications for more than one country.','consider the implications Have you considered the implications of your choice?','discuss the implications The paper discusses the implications of the agreement.','study/examine the implications He has studied the implications of recent technical innovations.','realize/grasp the implications (= understand what they are ) The government has been slow to grasp the implications of the current teacher shortage.']::text[],'[{"sentence":"What are the implications of these proposals?","translation":"پیامدهای این پیشنهادات چیست؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001406155.mp3"},{"sentence":"This election has profound implications for the future of U.S. democracy.","translation":"این انتخابات پیامدهای عمیقی برای آینده دموکراسی ایالات متحده دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709353.mp3"},{"sentence":"His talk will examine the wider implications of the Internet revolution.","translation":"سخنرانی او پیامدهای گسترده تر انقلاب اینترنت را بررسی خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709361.mp3"}]'::jsonb,3),
('a8361307-47f4-5004-a411-24f70bd1732f','38b25d80-8c97-51b9-ba7e-4089ea8a62e6',2,null,null,'spoken & written','a situation in which it is shown or suggested that someone or something is involved in a crime or a dishonest act','[ uncountable ]',null,'وضعیتی که در آن نشان داده می شود یا پیشنهاد می شود که کسی یا چیزی در یک جنایت یا یک عمل غیر صادقانه دخیل است','{}'::text[],'{}'::text[],array['important/serious implications The results of the experiment could have important implications for scientists.','major implications (= very important or serious ) The lack of affordable housing has major implications for families living in rural areas.','profound implications (= extremely important or serious ) The transformation of Europe has profound implications for the defence industries.','far-reaching implications (= causing things to change in an important way ) The cuts in social security benefits had far-reaching implications for ethnic minorities.','the wider implications (= affecting more people or society in general ) What are the wider implications of this change in the law?','the full implications (= all the different effects ) The full implications of the decision will become clear over the next few weeks.','possible implications We discussed the possible implications of oil price rises.','practical implications Academic research often has practical implications.','financial implications Managers must be aware of the financial implications of their decisions.','political implications The court’s decision could have far-reaching political implications.','legal implications We have taken advice on the legal implications of our activities.','social implications She’s studying the social implications of different patterns of work.','have implications This is an environmental disaster which will have implications for more than one country.','consider the implications Have you considered the implications of your choice?','discuss the implications The paper discusses the implications of the agreement.','study/examine the implications He has studied the implications of recent technical innovations.','realize/grasp the implications (= understand what they are ) The government has been slow to grasp the implications of the current teacher shortage.']::text[],'[{"sentence":"the implication of the former Chief of Staff in a major scandal","translation":"نقش رئیس سابق ستاد در یک رسوایی بزرگ","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001406181.mp3"}]'::jsonb,1),
('da04d776-108c-5fed-bf24-5780e136e80b','38b25d80-8c97-51b9-ba7e-4089ea8a62e6',3,null,null,'spoken & written','a suggestion that is not made directly but that people are expected to understand or accept','[ countable, uncountable ]',null,'پیشنهادی که مستقیماً ارائه نمی شود، اما انتظار می رود مردم آن را درک کنند یا بپذیرند','{}'::text[],'{}'::text[],array['important/serious implications The results of the experiment could have important implications for scientists.','major implications (= very important or serious ) The lack of affordable housing has major implications for families living in rural areas.','profound implications (= extremely important or serious ) The transformation of Europe has profound implications for the defence industries.','far-reaching implications (= causing things to change in an important way ) The cuts in social security benefits had far-reaching implications for ethnic minorities.','the wider implications (= affecting more people or society in general ) What are the wider implications of this change in the law?','the full implications (= all the different effects ) The full implications of the decision will become clear over the next few weeks.','possible implications We discussed the possible implications of oil price rises.','practical implications Academic research often has practical implications.','financial implications Managers must be aware of the financial implications of their decisions.','political implications The court’s decision could have far-reaching political implications.','legal implications We have taken advice on the legal implications of our activities.','social implications She’s studying the social implications of different patterns of work.','have implications This is an environmental disaster which will have implications for more than one country.','consider the implications Have you considered the implications of your choice?','discuss the implications The paper discusses the implications of the agreement.','study/examine the implications He has studied the implications of recent technical innovations.','realize/grasp the implications (= understand what they are ) The government has been slow to grasp the implications of the current teacher shortage.']::text[],'[{"sentence":"They are called ‘Supertrams’, the implication being that (= which is meant to suggest that ) they are more advanced than earlier models.","translation":"آنها \"Supertrams\" نامیده می شوند، به این معنی که (= که به این معنی است که) آنها پیشرفته تر از مدل های قبلی هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709369.mp3"},{"sentence":"The law bans organized protests and, by implication, any form of opposition.","translation":"این قانون اعتراضات سازمان یافته و به طور ضمنی هرگونه مخالفت را ممنوع می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001406169.mp3"}]'::jsonb,2),
('68421775-9cc1-507d-81be-1e04dc77a3ff','6adb11de-e4c9-5e6f-97d6-e43daef463cb',1,null,null,'spoken & written','the act of improving something, or the state of being improved','[ countable, uncountable ]',null,'بهبود، اصلاح؛ ارتقاء (وضعیت)','{}'::text[],'{}'::text[],array['be an improvement (on something) This version of the software is a clear improvement on its predecessor.','see/notice an improvement After taking the tablets, he noticed some improvement in his energy levels.','show an improvement The sales figures show a major improvement.','represent an improvement (= be an improvement ) A pre-tax profit of 4.3 million pounds represents a 5% improvement on last year.','a big improvement The situation today is a big improvement on the 1980s.','a great/vast/major improvement (= very big ) The new computer system was a vast improvement.','a dramatic improvement (= very big and quick ) With the new treatment we saw a dramatic improvement in his condition.','a significant/substantial/considerable improvement (= quite big ) There has been a considerable improvement in trading conditions.','a marked/noticeable improvement (= that people can notice ) Joanna''s work showed a marked improvement.','a slight improvement Sales figures have shown a slight improvement this month.','a gradual improvement There has been a gradual improvement in educational standards.','a general improvement There has been a general improvement in the standard of living.','a continuous/steady improvement (= happening slowly and gradually ) The following two seasons saw a steady improvement in the team''s performance.','further improvement (= more improvement ) We feel there is room for further improvement.','signs of improvement The patient is showing signs of improvement.','room for improvement (= the possibility that something could be done better ) There''s room for improvement in the way the tickets are sold.']::text[],'[{"sentence":"There’s been a big improvement in the children’s behaviour.","translation":"پیشرفت زیادی در رفتار بچه ها ایجاد شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001410112.mp3"},{"sentence":"an improvement on earlier models","translation":"بهبود در مدل های قبلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709704.mp3"},{"sentence":"We need to carry out some improvements to the system.","translation":"ما باید برخی از بهبودها را در سیستم انجام دهیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709705.mp3"},{"sentence":"Our results have shown some improvement this month.","translation":"نتایج ما در این ماه مقداری بهبود را نشان داده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000832.mp3"}]'::jsonb,4),
('3a88144f-c25e-53ce-ad5b-92a503cb490d','6adb11de-e4c9-5e6f-97d6-e43daef463cb',2,null,null,'spoken & written','a change or addition that improves something','[ countable ]',null,'تغییر یا اضافه ای که چیزی را بهبود می بخشد','{}'::text[],'{}'::text[],array['be an improvement (on something) This version of the software is a clear improvement on its predecessor.','see/notice an improvement After taking the tablets, he noticed some improvement in his energy levels.','show an improvement The sales figures show a major improvement.','represent an improvement (= be an improvement ) A pre-tax profit of 4.3 million pounds represents a 5% improvement on last year.','a big improvement The situation today is a big improvement on the 1980s.','a great/vast/major improvement (= very big ) The new computer system was a vast improvement.','a dramatic improvement (= very big and quick ) With the new treatment we saw a dramatic improvement in his condition.','a significant/substantial/considerable improvement (= quite big ) There has been a considerable improvement in trading conditions.','a marked/noticeable improvement (= that people can notice ) Joanna''s work showed a marked improvement.','a slight improvement Sales figures have shown a slight improvement this month.','a gradual improvement There has been a gradual improvement in educational standards.','a general improvement There has been a general improvement in the standard of living.','a continuous/steady improvement (= happening slowly and gradually ) The following two seasons saw a steady improvement in the team''s performance.','further improvement (= more improvement ) We feel there is room for further improvement.','signs of improvement The patient is showing signs of improvement.','room for improvement (= the possibility that something could be done better ) There''s room for improvement in the way the tickets are sold.']::text[],'[{"sentence":"Are you making some improvements to your home?","translation":"آیا در خانه خود اصلاحاتی انجام می دهید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001410127.mp3"}]'::jsonb,1),
('3e0d76de-3a5b-5f0b-8f9c-ec5e7df3953d','0bd18cd9-7d7c-5a4f-9ae8-b7aaa845635f',1,null,null,'spoken & written','to include something as part of a group, system, plan etc',null,null,'درخود گنجاندن، ادغام کردن؛ ثبت کردن (شرکت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We’ve incorporated many environmentally friendly features into the design of the building.","translation":"ما بسیاری از ویژگی های سازگار با محیط زیست را در طراحی ساختمان گنجانده ایم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001372874.mp3"},{"sentence":"Our original proposals were not incorporated in the new legislation.","translation":"پیشنهادات اولیه ما در قانون جدید گنجانده نشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001372875.mp3"}]'::jsonb,2),
('d9f334b6-15ad-5daf-93f8-6ead34131d18','bdc29804-2f58-5a8c-9f8e-fc7945982dba',1,null,null,'spoken & written','a serious British newspaper which generally supports liberal political ideas. The same company produces a similar paper on Sundays, called the Independent on Sunday .',null,null,'مستقل، بی‌طرف؛ خودکفا (مالی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('1386c310-066a-5d61-a4a8-17af7021377a','2740c57d-d4a7-5644-a2d0-3aa70a1a8689',1,'not owned/controlled by something','تحت مالکیت/کنترل چیزی نیست','spoken & written','an independent organization is not owned or controlled by, or does not receive money from, another organization or the government','[ usually before noun ]',null,'یک سازمان مستقل تحت مالکیت یا کنترل نیست، یا از سازمان یا دولت دیگری پول دریافت نمی کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There are plans to split the corporation into a number of smaller independent companies.","translation":"برنامه هایی برای تقسیم شرکت به تعدادی شرکت مستقل کوچکتر وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733616.mp3"},{"sentence":"an independent charity","translation":"یک موسسه خیریه مستقل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733617.mp3"},{"sentence":"small independent bookshops","translation":"کتابفروشی های کوچک مستقل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733618.mp3"},{"sentence":"We need a central bank that is independent of the government.","translation":"ما به یک بانک مرکزی مستقل از دولت نیاز داریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733621.mp3"},{"sentence":"schools in the independent sector","translation":"مدارس در بخش مستقل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733622.mp3"},{"sentence":"independent television companies","translation":"شرکت های تلویزیونی مستقل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733627.mp3"}]'::jsonb,6),
('dbcfeda2-5681-56fd-a489-cd4975f16eb8','2740c57d-d4a7-5644-a2d0-3aa70a1a8689',2,'fair','منصفانه','spoken & written','an independent organization or person is not involved in a particular situation, and can therefore be trusted to be fair in judging it','[ usually before noun ]',null,'یک سازمان یا شخص مستقل در یک موقعیت خاص درگیر نیست، بنابراین می توان به او اعتماد کرد که در قضاوت آن منصف است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an independent panel of scientists","translation":"پانل مستقلی از دانشمندان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733634.mp3"},{"sentence":"An independent body (= group of people who work together ) has been set up to monitor government spending.","translation":"یک نهاد مستقل (= گروهی از افرادی که با هم کار می کنند) برای نظارت بر هزینه های دولت ایجاد شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733635.mp3"},{"sentence":"There were no independent witnesses to the shooting.","translation":"هیچ شاهد مستقلی برای تیراندازی وجود نداشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733640.mp3"},{"sentence":"Human rights groups have called for an independent inquiry into the killings.","translation":"گروه های حقوق بشر خواستار تحقیق مستقل در مورد این قتل شده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733644.mp3"},{"sentence":"the results of an independent study","translation":"نتایج یک مطالعه مستقل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733645.mp3"}]'::jsonb,5),
('b94f01c2-f823-5310-bb74-744874c8cabb','2740c57d-d4a7-5644-a2d0-3aa70a1a8689',3,'country','کشور','spoken & written','an independent country is not governed or controlled by another country',null,null,'یک کشور مستقل توسط کشور دیگری اداره یا کنترل نمی شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"India became independent in 1947.","translation":"هند در سال 1947 مستقل شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001376398.mp3"}]'::jsonb,1),
('0dc753ad-7980-5c42-af18-ecc9e089bfb3','2740c57d-d4a7-5644-a2d0-3aa70a1a8689',4,'person','شخص','spoken & written','confident and able to do things by yourself in your own way, without needing help or advice from other people',null,null,'با اعتماد به نفس و قادر به انجام کارها به تنهایی به روش خود، بدون نیاز به کمک یا نصیحت دیگران','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Now that my sons are more independent, I have more time for myself.","translation":"حالا که پسرانم استقلال بیشتری دارند، وقت بیشتری برای خودم دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733649.mp3"},{"sentence":"an independent young woman","translation":"یک زن جوان مستقل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733650.mp3"},{"sentence":"He’s helping other people with spinal injuries to lead an independent life.","translation":"او به سایر افراد مبتلا به آسیب های ستون فقرات کمک می کند تا زندگی مستقلی داشته باشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733651.mp3"},{"sentence":"By this age, the child becomes relatively independent of his mother.","translation":"در این سن، کودک نسبتاً از مادرش مستقل می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001376413.mp3"},{"sentence":"It was always very important to me to be financially independent .","translation":"همیشه استقلال مالی برای من خیلی مهم بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001376418.mp3"},{"sentence":"Robert aimed to be independent of his parents by the time he was twenty.","translation":"رابرت قصد داشت تا بیست سالگی از والدینش مستقل باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001376421.mp3"}]'::jsonb,6),
('8f8215aa-9f63-576f-a885-00b3437847e9','2740c57d-d4a7-5644-a2d0-3aa70a1a8689',5,null,null,'spoken & written',null,null,'independent study/learning','مستقل، بی‌طرف؛ خودکفا (مالی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ccd731e8-5268-5220-ba2c-9ce72a427442','2740c57d-d4a7-5644-a2d0-3aa70a1a8689',6,null,null,'spoken & written',null,null,'woman/man etc of independent means','مستقل، بی‌طرف؛ خودکفا (مالی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('8879cba2-c7fe-5e7b-a319-20d3e9f176be','2740c57d-d4a7-5644-a2d0-3aa70a1a8689',7,'separate','جدا کردن','spoken & written','if one thing is independent of another, the two are not connected , or the second thing does not influence the first',null,null,'اگر یک چیز مستقل از چیز دیگر باشد، این دو به هم مرتبط نیستند یا چیز دوم بر اولی تأثیر نمی گذارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"reports from two separate sources entirely independent of one another","translation":"گزارشات از دو منبع جداگانه کاملا مستقل از یکدیگر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001376444.mp3"},{"sentence":"Three independent studies all arrived at the same conclusion.","translation":"سه مطالعه مستقل همگی به یک نتیجه رسیدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733662.mp3"}]'::jsonb,2),
('74a78166-1ce2-5262-abfc-7c8f18228bb7','2740c57d-d4a7-5644-a2d0-3aa70a1a8689',8,'politician','سیاستمدار','spoken & written','an independent politician does not belong to a particular party','[ usually before noun ]',null,'یک سیاستمدار مستقل به حزب خاصی تعلق ندارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Independent candidates won three seats.","translation":"نامزدهای مستقل سه کرسی به دست آوردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733670.mp3"}]'::jsonb,1),
('15326550-fd6f-58b8-8ad7-3b9523f32980','8543a1a7-5a8c-5272-ab1c-6ec9d9957782',1,null,null,'spoken & written','a politician who does not belong to a political party',null,null,'سیاستمداری که به یک حزب سیاسی تعلق ندارد','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('dda806e8-fba0-5805-b670-ae1d66ab2475','705a508a-a26e-524f-8209-fa847f2c2a49',1,null,null,'spoken & written','facts or details that tell you something about a situation , person, event etc',null,'inside information','اطلاعات، خبر؛ رساندن (داده)؛ معلومات','{}'::text[],'{}'::text[],array['useful/valuable The information he gave me was very useful.','correct/accurate Are you sure this information is correct?','wrong/false He was jailed for providing false information to the police.','relevant (= about the subject you are interested in ) Some of the information in the article is not particularly relevant.','confidential/secret That information was confidential and should not have been passed on.','more/further/additional information For more information, visit our website.','new information The police have received new information about the case.','the latest information (= information that has been discovered very recently ) We have access to all the latest information.','the necessary information This leaflet should provide you with all the necessary information.','detailed information More detailed information is available free on request.','financial/economic information The financial information contained in the report is based on the company''s audited accounts.','background information (= information explaining what happened before the present situation ) He gave us some background information about the trial.','have information Do you have any information about coach trips to Oxford?','contain information The documents contained top secret information.','get/receive information It is vital that people receive the information they need.','give/provide information a booklet giving information about local education services','collect/gather information The job consisted of gathering information about consumer needs.','need information When I needed information for my report, Jack was always extremely helpful.','look for information ( also seek information formal ) Journalists going to the building to seek information were denied entry.','exchange information (= give information to each other ) The meetings provided an opportunity to exchange information.','disseminate information formal (= give it to a lot of people ) The internet plays a key role in disseminating information.','a piece/bit of information ( also an item of information formal ) He provided me with several useful pieces of information.','a source of information (= someone or something that can provide information ) Newspapers are valuable sources of information.']::text[],'[{"sentence":"I need more information.","translation":"من به اطلاعات بیشتری نیاز دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001411861.mp3"},{"sentence":"We have received information that Grant may have left the country.","translation":"ما اطلاعاتی دریافت کردیم مبنی بر اینکه گرانت ممکن است کشور را ترک کرده باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001411864.mp3"},{"sentence":"The book contains information about a wide variety of subjects.","translation":"این کتاب حاوی اطلاعاتی در مورد موضوعات مختلف است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001411867.mp3"},{"sentence":"My information is that Gary wants to stay with the club.","translation":"اطلاعات من این است که گری می خواهد در باشگاه بماند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001744965.mp3"},{"sentence":"I need some information about hotels.","translation":"من به اطلاعاتی در مورد هتل ها نیاز دارم.","audio_url":null},{"sentence":"The information is strictly confidential.","translation":"اطلاعات کاملاً محرمانه است.","audio_url":null},{"sentence":"He told me an interesting piece of information.","translation":"او اطلاعات جالبی به من گفت.","audio_url":null}]'::jsonb,7),
