('f8c10a68-de18-52bb-92e4-554d60bf0113','0806bc62-9634-56a8-8271-3b8605a35cd0',1,null,null,'spoken & written','the government organization responsible for the mail in the UK. The Post Office also manages the payment of state pension s and social security payments. Its official name is the Roysl Mail.',null,null,'سازمان دولتی مسئول پست در بریتانیا. اداره پست همچنین پرداخت مستمری های دولتی و پرداخت های تامین اجتماعی را مدیریت می کند. نام رسمی آن Roysl Mail است.','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('1edd6d04-c0d7-55fe-8c63-cb972c857fd6','17f44a4f-c33c-5a96-8694-91309b0a2367',1,null,null,'especially spoken','almost',null,null,'تقریباً، عملاً؛ در عمل (معنایی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’ve read practically all of his books.","translation":"من عملاً همه کتاب های او را خوانده ام.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317455.mp3"},{"sentence":"She sees him practically every day.","translation":"او را عملا هر روز می بیند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317456.mp3"},{"sentence":"It’s practically impossible to predict what will happen.","translation":"پیش بینی اینکه چه اتفاقی خواهد افتاد عملا غیرممکن است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567997.mp3"},{"sentence":"The two designs were practically identical.","translation":"این دو طرح عملا یکسان بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568001.mp3"}]'::jsonb,4),
('bd871539-ec41-5375-b11d-067ef2ba4da2','17f44a4f-c33c-5a96-8694-91309b0a2367',2,null,null,'spoken & written','in a sensible way which takes account of problems',null,null,'به روشی معقول که مشکلات را در نظر بگیرد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘But how can we pay for it?’ said John practically.","translation":"جان عملاً گفت: \"اما چگونه می توانیم هزینه آن را بپردازیم؟\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317460.mp3"}]'::jsonb,1),
('f716b075-aba1-5312-a904-151bf283456b','374b8015-baea-5191-ab78-cf8f3da871d1',1,null,null,'spoken & written','the process of preparing something or preparing for something','[ singular, uncountable ]',null,'آماده‌سازی، پیش‌بینی (کار)؛ حصول (آماده‌سازی)','{}'::text[],'{}'::text[],array['careful preparation Moving to a new house requires careful preparation.','thorough preparation (= very careful and detailed ) Thorough preparation is the best way to do well in an exam.','meticulous preparation (= extremely careful not to miss any details ) The robbery took place after months of meticulous preparation.','good/ideal preparation (= very useful ) The game was good preparation for our match at Torquay next week.','adequate/proper preparation You cannot go on a dangerous trip like this without adequate preparation.','do some/no preparation He had obviously done no preparation for the meeting.','need/require preparation Important competitions need proper preparation.','be in preparation formal (= used to say that something is being prepared ) Reports are in preparation.']::text[],'[{"sentence":"This dish is good for dinner parties because much of the preparation can be done ahead of time.","translation":"این غذا برای مهمانی های شام خوب است زیرا بسیاری از کارهای آماده سازی را می توان زودتر از موعد انجام داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568637.mp3"},{"sentence":"Business training is a good preparation for any career.","translation":"آموزش کسب و کار آمادگی خوبی برای هر شغلی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322799.mp3"},{"sentence":"the preparation of the budget","translation":"تهیه بودجه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322802.mp3"},{"sentence":"He is practising every day, in preparation for the ice-skating championship.","translation":"او هر روز در حال تمرین است تا برای مسابقات قهرمانی اسکیت روی یخ آماده شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322806.mp3"},{"sentence":"Plans for the new school are now in preparation .","translation":"برنامه های مدرسه جدید اکنون در حال آماده سازی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568638.mp3"},{"sentence":"a course in food service and food preparation","translation":"دوره خدمات غذا و تهیه غذا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568644.mp3"}]'::jsonb,6),
('9480d70a-727b-51f4-ab04-5de5947b62e8','374b8015-baea-5191-ab78-cf8f3da871d1',2,null,null,'spoken & written',null,null,'preparations','آماده‌سازی، پیش‌بینی (کار)؛ حصول (آماده‌سازی)','{}'::text[],'{}'::text[],array['careful preparation Moving to a new house requires careful preparation.','thorough preparation (= very careful and detailed ) Thorough preparation is the best way to do well in an exam.','meticulous preparation (= extremely careful not to miss any details ) The robbery took place after months of meticulous preparation.','good/ideal preparation (= very useful ) The game was good preparation for our match at Torquay next week.','adequate/proper preparation You cannot go on a dangerous trip like this without adequate preparation.','do some/no preparation He had obviously done no preparation for the meeting.','need/require preparation Important competitions need proper preparation.','be in preparation formal (= used to say that something is being prepared ) Reports are in preparation.']::text[],'[]'::jsonb,0),
('c4d5cc36-3409-56b3-9852-a747a1db085a','374b8015-baea-5191-ab78-cf8f3da871d1',3,null,null,'formal','a mixture that has been prepared and that is used for a particular purpose , especially as a medicine or to make your skin more attractive','[ countable ]',null,'مخلوطی که تهیه شده و برای هدف خاصی استفاده می شود، مخصوصاً به عنوان دارو یا برای ایجاد جذابیت بیشتر پوست شما','{}'::text[],'{}'::text[],array['careful preparation Moving to a new house requires careful preparation.','thorough preparation (= very careful and detailed ) Thorough preparation is the best way to do well in an exam.','meticulous preparation (= extremely careful not to miss any details ) The robbery took place after months of meticulous preparation.','good/ideal preparation (= very useful ) The game was good preparation for our match at Torquay next week.','adequate/proper preparation You cannot go on a dangerous trip like this without adequate preparation.','do some/no preparation He had obviously done no preparation for the meeting.','need/require preparation Important competitions need proper preparation.','be in preparation formal (= used to say that something is being prepared ) Reports are in preparation.']::text[],'[{"sentence":"a new preparation for cleansing the skin","translation":"آماده سازی جدید برای پاکسازی پوست","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322830.mp3"}]'::jsonb,1),
('de789773-15f6-5fde-88fb-1c6f4c3d58fc','fa990fe7-0a8c-53b6-81f9-0025dc208501',1,null,null,'spoken & written','when a charge is made against someone for a crime , or when someone is judged for a crime in a court of law','[ countable, uncountable ]',null,'تعقیب قضایی، تعقیب (متهم)؛ تعقیب (قضایی)','{}'::text[],'{}'::text[],array['(a) criminal prosecution Failure to hand over the documents could result in criminal prosecution.','a private prosecution The victim''s widow is considering a private prosecution.','successful We do not yet have enough evidence for a successful prosecution.','bring a prosecution against somebody (= prosecute them ) The police did not bring a prosecution against him.','face prosecution The owners of a golf course are facing prosecution for blocking footpaths.','escape/avoid prosecution He was lucky to escape prosecution.','be liable to/for prosecution formal (= may be prosecuted ) Businesses which do not meet the standards required are liable for prosecution.','immunity from prosecution formal (= the state of being protected from prosecution ) He gave information to the police in return for immunity from prosecution.']::text[],'[{"sentence":"a criminal prosecution","translation":"یک تعقیب کیفری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591705.mp3"},{"sentence":"Walters could face prosecution for his role in the robbery.","translation":"والترز ممکن است به دلیل نقشش در این سرقت تحت پیگرد قانونی قرار گیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591710.mp3"},{"sentence":"the prosecution of war criminals","translation":"محاکمه جنایتکاران جنگی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591716.mp3"},{"sentence":"The evidence is not sufficient to bring a prosecution against him.","translation":"شواهد برای پیگرد قانونی او کافی نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000304017.mp3"}]'::jsonb,4),
('21568909-bf86-5089-9589-5535907408cf','fa990fe7-0a8c-53b6-81f9-0025dc208501',2,null,null,'spoken & written',null,null,'the prosecution','تعقیب قضایی، تعقیب (متهم)؛ تعقیب (قضایی)','{}'::text[],'{}'::text[],array['(a) criminal prosecution Failure to hand over the documents could result in criminal prosecution.','a private prosecution The victim''s widow is considering a private prosecution.','successful We do not yet have enough evidence for a successful prosecution.','bring a prosecution against somebody (= prosecute them ) The police did not bring a prosecution against him.','face prosecution The owners of a golf course are facing prosecution for blocking footpaths.','escape/avoid prosecution He was lucky to escape prosecution.','be liable to/for prosecution formal (= may be prosecuted ) Businesses which do not meet the standards required are liable for prosecution.','immunity from prosecution formal (= the state of being protected from prosecution ) He gave information to the police in return for immunity from prosecution.']::text[],'[]'::jsonb,0),
('cb52379b-2c43-5486-bc8a-154e17604093','fa990fe7-0a8c-53b6-81f9-0025dc208501',3,null,null,'formal','when you do something that is your job','[ uncountable ]',null,'وقتی کاری را انجام می دهید که وظیفه شماست','{}'::text[],'{}'::text[],array['(a) criminal prosecution Failure to hand over the documents could result in criminal prosecution.','a private prosecution The victim''s widow is considering a private prosecution.','successful We do not yet have enough evidence for a successful prosecution.','bring a prosecution against somebody (= prosecute them ) The police did not bring a prosecution against him.','face prosecution The owners of a golf course are facing prosecution for blocking footpaths.','escape/avoid prosecution He was lucky to escape prosecution.','be liable to/for prosecution formal (= may be prosecuted ) Businesses which do not meet the standards required are liable for prosecution.','immunity from prosecution formal (= the state of being protected from prosecution ) He gave information to the police in return for immunity from prosecution.']::text[],'[{"sentence":"the prosecution of her duties","translation":"پیگیری وظایف او","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000304035.mp3"}]'::jsonb,1),
('6f852e2a-61ae-5f1c-a1b3-e73e076b81f5','6f65de57-33d6-5f93-b1b9-617a43cfde19',1,null,null,'spoken & written','the process of printing a book, magazine etc and offering it for sale','[ uncountable ]',null,'انتشار، چاپ (کتاب)؛ انتشار (خبر)؛ انتشار (مقاله)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She was in England for the publication of her new book.","translation":"او برای چاپ کتاب جدیدش در انگلیس بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000270210.mp3"},{"sentence":"He spent his holiday writing reviews for publication.","translation":"او تعطیلات خود را صرف نوشتن نقد برای انتشار کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561804.mp3"}]'::jsonb,2),
('e389caf6-d3af-561e-9760-fb257f845d59','6f65de57-33d6-5f93-b1b9-617a43cfde19',2,null,null,'spoken & written','a book, magazine etc','[ countable ]',null,'یک کتاب، مجله و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was the author of 70 major scientific publications.","translation":"او نویسنده 70 مقاله مهم علمی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000270215.mp3"},{"sentence":"a weekly publication","translation":"یک نشریه هفتگی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561805.mp3"}]'::jsonb,2),
('30838b27-20b9-556d-a9e1-4e014b61a20f','6f65de57-33d6-5f93-b1b9-617a43cfde19',3,null,null,'spoken & written','when information is printed in a book, magazine etc so that the public can read it','[ uncountable ]',null,'هنگامی که اطلاعات در یک کتاب، مجله و غیره چاپ می شود تا عموم بتوانند آن را مطالعه کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the publication of the company’s annual results","translation":"انتشار نتایج سالانه شرکت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561808.mp3"}]'::jsonb,1),
('d99dbd02-cbf5-5201-aac8-ae55f1449063','3c5b9e97-8064-5cb0-8d0f-60c028436637',1,null,null,'spoken & written','the act of realizing and accepting that something is true or important','[ singular, uncountable ]',null,'شناسایی، به‌رسمیت‌شناختن؛ شناخت (عام)؛ اعتبار (برند)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Don’s recognition of the importance of Suzy in his life","translation":"درک دان از اهمیت سوزی در زندگی اش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760971.mp3"},{"sentence":"There is general recognition that the study techniques of many students are weak.","translation":"شناخت کلی وجود دارد که تکنیک های مطالعه بسیاری از دانش آموزان ضعیف است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001771332.mp3"},{"sentence":"official recognition of the need for jail reform","translation":"به رسمیت شناختن رسمی نیاز به اصلاحات در زندان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001614008.mp3"}]'::jsonb,3),
('5a2e9189-d7b2-581a-a5fa-72bf0fa2b6a0','3c5b9e97-8064-5cb0-8d0f-60c028436637',2,null,null,'spoken & written','public respect and thanks for someone’s work or achievements','[ singular, uncountable ]',null,'احترام عمومی و تشکر از کار یا دستاوردهای کسی','{}'::text[],'{}'::text[],array['achieve recognition Toni has been striving to achieve recognition for the past ten years.','receive/be given/get recognition Younger women artists are now getting wider recognition.','win/gain recognition The company has won recognition for its customer service.','deserve recognition They deserve recognition for the tremendous job they are doing.','national/international/worldwide recognition Like many pianists, he first achieved international recognition by winning a competition.','public recognition He won public recognition for his work when he was awarded an MBE.','professional recognition My father craved professional recognition.','proper recognition Frank Norris has never received proper recognition as a great novelist.','wider recognition She deserves wider recognition.']::text[],'[{"sentence":"He has achieved recognition and respect as a scientist.","translation":"او به عنوان یک دانشمند به رسمیت و احترام دست یافته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760959.mp3"},{"sentence":"The importance of voluntary organizations in the economy still needs to be given recognition .","translation":"اهمیت سازمان های داوطلبانه در اقتصاد هنوز باید به رسمیت شناخته شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001614009.mp3"},{"sentence":"He was presented with a gold watch in recognition of his service to the company.","translation":"به پاس خدماتش به شرکت، یک ساعت طلایی به او اهدا شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001614012.mp3"}]'::jsonb,3),
('6ee859c2-9b36-5083-aee4-101dfcf7f0aa','3c5b9e97-8064-5cb0-8d0f-60c028436637',3,null,null,'spoken & written','the act of knowing someone or something because you have known or learned about them in the past','[ uncountable ]',null,'عمل شناختن کسی یا چیزی به این دلیل که در گذشته او را می‌شناخته‌اید یا درباره‌اش یاد گرفته‌اید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He stared at her, but there was no sign of recognition .","translation":"به او خیره شد، اما هیچ نشانی از شناسایی وجود نداشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760950.mp3"},{"sentence":"The bakery business has changed beyond all recognition in the last 10 years.","translation":"کسب و کار نانوایی در 10 سال گذشته فراتر از هر شناختی تغییر کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760954.mp3"}]'::jsonb,2),
('7db7f7a6-820f-5e51-859b-cf8e4485f27f','3c5b9e97-8064-5cb0-8d0f-60c028436637',4,null,null,'spoken & written','the act of officially accepting that an organization , government, person etc has legal or official authority','[ uncountable ]',null,'عمل پذیرش رسمی اینکه یک سازمان، دولت، شخص و غیره دارای اختیار قانونی یا رسمی است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the recognition of Latvia as an independent state","translation":"به رسمیت شناختن لتونی به عنوان یک کشور مستقل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760979.mp3"},{"sentence":"the government’s failure to achieve international recognition","translation":"شکست دولت در دستیابی به رسمیت بین المللی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001614018.mp3"}]'::jsonb,2),
('44ff4349-f997-5761-9b8a-30ba0606dc6a','3c5b9e97-8064-5cb0-8d0f-60c028436637',5,null,null,'spoken & written',null,null,'speech recognition','شناسایی، به‌رسمیت‌شناختن؛ شناخت (عام)؛ اعتبار (برند)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('3815ac17-935c-5127-8bed-e5ffede213d5','66438451-a1d8-5175-a621-7d4ca2fda7bd',1,null,null,'spoken & written','when you get something that is newer or better than the one you had before','[ uncountable ]',null,'جایگزین، بدل؛ جابه‌جایی (شغل)؛ جایگزین (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Our old car is badly in need of replacement.","translation":"ماشین قدیمی ما به شدت نیاز به تعویض دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000776272.mp3"},{"sentence":"replacement windows","translation":"پنجره های تعویضی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001562730.mp3"}]'::jsonb,2),
('2aed099c-83da-5368-b8c1-5b1ee10ec828','66438451-a1d8-5175-a621-7d4ca2fda7bd',2,null,null,'spoken & written',null,null,'knee/hip/joint replacement','جایگزین، بدل؛ جابه‌جایی (شغل)؛ جایگزین (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('a641b4a7-7ce8-549f-8b4a-5cf2f1b48847','66438451-a1d8-5175-a621-7d4ca2fda7bd',3,null,null,'spoken & written','someone or something that replaces another person or thing','[ countable ]',null,'کسی یا چیزی که جایگزین شخص یا چیز دیگری می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It was difficult to find a replacement for Ted.","translation":"یافتن جایگزینی برای تد دشوار بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000776279.mp3"}]'::jsonb,1),
('ccfd48e8-f89d-5ac3-b769-eb36c858251c','598fe7a1-6a3b-5389-ab36-c8d634449239',1,null,null,'spoken & written','something that someone needs or asks for',null,null,'الزام، نیاز (لازم)؛ شرط (پذیرش)','{}'::text[],'{}'::text[],array['meet a requirement (= have or do what is needed ) We finally found a house that seemed to meet all of our requirements.','satisfy/fulfil a requirement formal (= meet them ) Our aim is to satisfy our customers’ requirements.','comply with requirements formal (= have or do what a rule or law says is necessary ) Failure to comply with these requirements is a criminal offence.','impose requirements formal (= state that something has to be done ) Because the regulations impose new requirements on small businesses, they will prove costly.','suit somebody’s requirements (= be suitable for someone in a particular situation ) You could design and build your own house to suit your requirements.','a special requirement He modified the car to suit his own special requirements.','a basic requirement Water is a basic requirement of life.','an essential requirement Confidence is an essential requirement for success.','a minimum requirement That certificate is a minimum requirement for entry to music college.','a legal/statutory requirement There is no legal requirement to carry identity papers.','safety requirements All companies are required to meet Health and Safety requirements.','entry requirements (= the skills, qualifications etc you must have in order to enter a school, university, or country, or to do a course ) Applicants must satisfy the normal entry requirements for the programme.','energy requirements (= the amount of energy a place or person needs ) 65 percent of the country’s energy requirements were met by imported oil.','be surplus to requirements British English (= be more than is needed ) The old school building is now surplus to requirements.']::text[],'[{"sentence":"The refugees’ main requirements are food and shelter.","translation":"نیازهای اصلی پناهندگان غذا و سرپناه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000743892.mp3"},{"sentence":"Potatoes can provide one-third of our daily requirement of vitamin C.","translation":"سیب زمینی می تواند یک سوم نیاز روزانه ما به ویتامین C را تامین کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607271.mp3"},{"sentence":"The new computer system will meet all our requirements.","translation":"سیستم کامپیوتری جدید تمام نیازهای ما را برآورده خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000743896.mp3"},{"sentence":"The increase in gas-fired power stations means traditional coal ones are becoming surplus to requirements.","translation":"افزایش نیروگاه‌های گازسوز به این معنی است که نیروگاه‌های سنتی زغال‌سنگ مازاد بر نیاز هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607272.mp3"}]'::jsonb,4),
('487fa9ba-ad50-5227-b69a-78cab049b248','598fe7a1-6a3b-5389-ab36-c8d634449239',2,null,null,'spoken & written','something that must be done because of a law or rule',null,null,'کاری که باید به دلیل یک قانون یا قانون انجام شود','{}'::text[],'{}'::text[],array['meet a requirement (= have or do what is needed ) We finally found a house that seemed to meet all of our requirements.','satisfy/fulfil a requirement formal (= meet them ) Our aim is to satisfy our customers’ requirements.','comply with requirements formal (= have or do what a rule or law says is necessary ) Failure to comply with these requirements is a criminal offence.','impose requirements formal (= state that something has to be done ) Because the regulations impose new requirements on small businesses, they will prove costly.','suit somebody’s requirements (= be suitable for someone in a particular situation ) You could design and build your own house to suit your requirements.','a special requirement He modified the car to suit his own special requirements.','a basic requirement Water is a basic requirement of life.','an essential requirement Confidence is an essential requirement for success.','a minimum requirement That certificate is a minimum requirement for entry to music college.','a legal/statutory requirement There is no legal requirement to carry identity papers.','safety requirements All companies are required to meet Health and Safety requirements.','entry requirements (= the skills, qualifications etc you must have in order to enter a school, university, or country, or to do a course ) Applicants must satisfy the normal entry requirements for the programme.','energy requirements (= the amount of energy a place or person needs ) 65 percent of the country’s energy requirements were met by imported oil.','be surplus to requirements British English (= be more than is needed ) The old school building is now surplus to requirements.']::text[],'[{"sentence":"If you are installing a new bathroom, it has to meet the requirements of the Building Regulations.","translation":"اگر در حال نصب حمام جدید هستید، باید الزامات مقررات ساختمان را رعایت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607279.mp3"},{"sentence":"Two measures have been introduced as legal requirements .","translation":"دو اقدام به عنوان الزامات قانونی معرفی شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001877085.mp3"}]'::jsonb,2),
('6426e892-1a2f-5916-ad66-ea41ff497e0b','598fe7a1-6a3b-5389-ab36-c8d634449239',3,null,null,'spoken & written','something, especially good examination results , that a college , employer etc says you must have in order to do something',null,null,'چیزی، به خصوص نتایج امتحان خوب، که یک کالج، کارفرما و غیره می گوید که برای انجام کاری باید داشته باشید','{}'::text[],'{}'::text[],array['meet a requirement (= have or do what is needed ) We finally found a house that seemed to meet all of our requirements.','satisfy/fulfil a requirement formal (= meet them ) Our aim is to satisfy our customers’ requirements.','comply with requirements formal (= have or do what a rule or law says is necessary ) Failure to comply with these requirements is a criminal offence.','impose requirements formal (= state that something has to be done ) Because the regulations impose new requirements on small businesses, they will prove costly.','suit somebody’s requirements (= be suitable for someone in a particular situation ) You could design and build your own house to suit your requirements.','a special requirement He modified the car to suit his own special requirements.','a basic requirement Water is a basic requirement of life.','an essential requirement Confidence is an essential requirement for success.','a minimum requirement That certificate is a minimum requirement for entry to music college.','a legal/statutory requirement There is no legal requirement to carry identity papers.','safety requirements All companies are required to meet Health and Safety requirements.','entry requirements (= the skills, qualifications etc you must have in order to enter a school, university, or country, or to do a course ) Applicants must satisfy the normal entry requirements for the programme.','energy requirements (= the amount of energy a place or person needs ) 65 percent of the country’s energy requirements were met by imported oil.','be surplus to requirements British English (= be more than is needed ) The old school building is now surplus to requirements.']::text[],'[{"sentence":"English 4 is a requirement for English majors.","translation":"زبان انگلیسی 4 برای رشته های انگلیسی الزامی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001770904.mp3"},{"sentence":"To find out about entry requirements for students, write to the college admissions board.","translation":"برای اطلاع از شرایط ورود به دانشگاه، به هیئت پذیرش کالج مکاتبه کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607282.mp3"},{"sentence":"The minimum requirement for the post was a degree in engineering.","translation":"حداقل شرط لازم برای این پست داشتن مدرک مهندسی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000743901.mp3"}]'::jsonb,3),
('053d616b-8141-52f9-998e-3f753604c642','b5ee15cf-ffb4-581f-99aa-f9095b370c95',1,null,null,'spoken & written','a residential part of a town consists of private houses, with no offices or factories',null,null,'مسکونی، سکونتی (ناحیه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a quiet residential neighbourhood","translation":"یک محله مسکونی آرام","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001770931.mp3"}]'::jsonb,1),
('af424497-881e-56ac-9332-2cd09cd8853a','b5ee15cf-ffb4-581f-99aa-f9095b370c95',2,null,null,'spoken & written','relating to homes rather than offices or businesses',null,null,'مربوط به خانه ها به جای دفاتر یا مشاغل','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"telephone services for residential customers","translation":"خدمات تلفنی برای مشتریان خانگی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607673.mp3"}]'::jsonb,1),
('f6f94ca3-b215-5676-a289-5e2cfcaa284e','b5ee15cf-ffb4-581f-99aa-f9095b370c95',3,null,null,'spoken & written',null,null,'residential course/school etc','مسکونی، سکونتی (ناحیه)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('1cf680fa-bd48-547b-bdc5-4a441516a5d8','f44ef832-66a5-50d1-8fc6-231495786a1b',1,null,null,'spoken & written','an occasion when you officially announce that you have decided to leave your job or an organization , or a written statement that says you will be leaving','[ countable, uncountable ]',null,'استعفا، کناره‌گیری؛ تسلیم (بی‌دعوی)؛ رضایت (اجباری)','{}'::text[],'{}'::text[],array['call for somebody''s resignation (= publicly ask for it ) After the defeat, there were calls for the coach''s resignation.','demand somebody''s resignation (= ask for it forcefully ) His political opponents demanded his resignation.','hand in your resignation (= say that you are going to leave an organization ) I''m thinking of handing in my resignation.','offer your resignation ( also tender/submit your resignation formal ) Claire apologized and offered her resignation. On the Monday afternoon, Sir John tendered his resignation to the Queen.','accept somebody''s resignation The prime minister reluctantly accepted his resignation.','reject/turn down somebody''s resignation Initially, his resignation was rejected. He offered his resignation but it was turned down by the prime minister.','withdraw your resignation (= say that you will not leave, after having said you would ) The president persuaded him to withdraw his resignation.','a letter of resignation He immediately wrote a letter of resignation.']::text[],'[{"sentence":"Illness forced his resignation.","translation":"بیماری او را مجبور به استعفا کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001337.mp3"},{"sentence":"Further resignations are expected later this week.","translation":"انتظار می رود استعفاهای بیشتری در اواخر این هفته ارائه شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001338.mp3"}]'::jsonb,2),
('6f760962-6374-5bcf-b8d2-e2b1c5a8cf21','f44ef832-66a5-50d1-8fc6-231495786a1b',2,null,null,'spoken & written','when someone calmly accepts a situation that cannot be changed, even though it is bad','[ uncountable ]',null,'وقتی کسی با آرامش شرایطی را می پذیرد که قابل تغییر نیست، حتی اگر بد باشد','{}'::text[],'{}'::text[],array['call for somebody''s resignation (= publicly ask for it ) After the defeat, there were calls for the coach''s resignation.','demand somebody''s resignation (= ask for it forcefully ) His political opponents demanded his resignation.','hand in your resignation (= say that you are going to leave an organization ) I''m thinking of handing in my resignation.','offer your resignation ( also tender/submit your resignation formal ) Claire apologized and offered her resignation. On the Monday afternoon, Sir John tendered his resignation to the Queen.','accept somebody''s resignation The prime minister reluctantly accepted his resignation.','reject/turn down somebody''s resignation Initially, his resignation was rejected. He offered his resignation but it was turned down by the prime minister.','withdraw your resignation (= say that you will not leave, after having said you would ) The president persuaded him to withdraw his resignation.','a letter of resignation He immediately wrote a letter of resignation.']::text[],'[{"sentence":"She gave a sigh of resignation.","translation":"او نفسی از استعفا کشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001876852.mp3"},{"sentence":"He accepted her decision with resignation.","translation":"او تصمیم او را با استعفا پذیرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000744881.mp3"}]'::jsonb,2),
('25c00c6d-a5e2-5044-a54f-4a4cf07ab140','d75971aa-6898-59e4-a0a2-b728dd7e7116',1,'guilty','گناهکار','spoken & written','if someone is responsible for an accident , mistake , crime etc, it is their fault or they can be blamed','[ not before noun ]',null,'مسؤول، پاسخ‌گو؛ مواظب (حس)؛ مسئول (کار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Police believe that the same man is responsible for three other murders in the area.","translation":"پلیس معتقد است که همین مرد مسئول سه قتل دیگر در منطقه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000746047.mp3"},{"sentence":"If anything goes wrong, I will hold you personally responsible .","translation":"اگر مشکلی پیش بیاید، من شخصاً شما را مسئول می دانم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001563070.mp3"},{"sentence":"We are determined to bring the people responsible to justice.","translation":"ما مصمم هستیم که افراد مسئول را به عدالت بسپاریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001991161.mp3"}]'::jsonb,3),
('86f329e5-8149-55da-afe1-95a978c26ad6','d75971aa-6898-59e4-a0a2-b728dd7e7116',2,'in charge of','مسئول','spoken & written','having a duty to be in charge of or to look after someone or something','[ not before noun ]',null,'وظیفه داشتن مسئول بودن یا مراقبت از کسی یا چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Mills is responsible for a budget of over $5 million.","translation":"میلز مسئول بودجه ای بالغ بر 5 میلیون دلار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000746061.mp3"},{"sentence":"The airline is legally responsible for the safety of its passengers.","translation":"شرکت هواپیمایی از نظر قانونی مسئول ایمنی مسافران خود است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001991162.mp3"},{"sentence":"He is responsible for recruiting and training new staff.","translation":"او مسئول جذب و آموزش کارکنان جدید است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001563078.mp3"}]'::jsonb,3),
('3f1f83ce-af06-5cbe-8c90-a62b4c941343','d75971aa-6898-59e4-a0a2-b728dd7e7116',3,'cause','علت','spoken & written','if something is responsible for a change, problem, event etc, it causes it','[ not before noun ]',null,'اگر چیزی مسئول تغییر، مشکل، رویداد و غیره باشد، باعث آن می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The floods were responsible for over a hundred deaths.","translation":"سیل عامل بیش از صد کشته بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000746087.mp3"}]'::jsonb,1),
('056bb809-707b-5d16-aad7-65c4285e0469','d75971aa-6898-59e4-a0a2-b728dd7e7116',4,'sensible','معقول','spoken & written','sensible and able to make good judgments, so that you can be trusted',null,null,'معقول و قادر به قضاوت خوب، به طوری که می توان به شما اعتماد کرد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You can leave the children with Billy – he’s very responsible.","translation":"می توانید بچه ها را به بیلی بسپارید - او بسیار مسئولیت پذیر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000746071.mp3"},{"sentence":"It’s time you started acting like a responsible adult.","translation":"وقت آن است که مانند یک بزرگسال مسئول رفتار کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001563082.mp3"}]'::jsonb,2),
('0e16274e-7f02-5e0d-9ca2-866304ec0986','d75971aa-6898-59e4-a0a2-b728dd7e7116',5,null,null,'spoken & written',null,null,'responsible job/position','مسؤول، پاسخ‌گو؛ مواظب (حس)؛ مسئول (کار)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
