('02add1fe-421f-5708-b18d-53780401fa43','e4bff2d9-7100-51d6-958e-b6999d8d59c6',2,null,null,'spoken & written','following ideas and methods that have existed for a long time, rather than doing anything new or different',null,null,'پیروی از ایده ها و روش هایی که برای مدت طولانی وجود داشته اند، به جای انجام هر کاری جدید یا متفاوت',array['conventional']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He has a traditional view of women.","translation":"او نگاه سنتی به زن دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001828038.mp3"},{"sentence":"I went to a very traditional school.","translation":"من به یک مدرسه بسیار سنتی رفتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000552582.mp3"},{"sentence":"traditional family values","translation":"ارزش های سنتی خانواده","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001736627.mp3"},{"sentence":"a traditional way of life","translation":"یک سبک زندگی سنتی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001736628.mp3"}]'::jsonb,4),
