('681cbcb0-c133-5cb5-8b0c-3d56e8647da2','c4ae5d6a-9d03-5f03-a706-4329c07dcf54',1,null,null,'spoken & written','someone who is unfortunate has something bad happen to them',null,null,'بدشانس، گرفتار (فرد)؛ تأسف‌بار (رخداد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"When we entered the room, the teacher was yelling at some unfortunate student.","translation":"وقتی وارد اتاق شدیم، معلم سر دانش آموز بدبخت فریاد می زد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001638605.mp3"}]'::jsonb,1),
('42550867-1a3d-5f7b-b527-98b4a823617f','c4ae5d6a-9d03-5f03-a706-4329c07dcf54',2,null,null,'spoken & written','an unfortunate situation, condition , quality etc is one that you wish was different',null,null,'وضعیت، وضعیت، کیفیت و غیره تاسف بار، شرایطی است که شما آرزو می کنید متفاوت باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an unfortunate turn of events","translation":"یک چرخش ناگوار از وقایع","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000549653.mp3"},{"sentence":"He has an unfortunate habit of repeating himself.","translation":"او عادت بدی دارد که خودش را تکرار می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001638606.mp3"},{"sentence":"It’s unfortunate that so few people seem willing to help.","translation":"مایه تاسف است که به نظر می رسد افراد کمی مایل به کمک هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001638607.mp3"},{"sentence":"It’s most unfortunate (= very unfortunate ) that your father can’t come to the wedding.","translation":"مایه تاسف است (= بسیار تاسف بار) که پدر شما نمی تواند به عروسی بیاید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000549658.mp3"}]'::jsonb,4),
