('ce60e845-0245-54af-af3b-5aee24660f34','fd0c3deb-3ef7-5cf8-91d9-d9edf47cc6cb',1,null,null,'spoken & written','as shown by something or stated by someone',null,null,'بر اساس، طبق، بنا به','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"According to the police, his attackers beat him with a blunt instrument.","translation":"به گفته پلیس، مهاجمان او را با ابزار بی‌نقص مورد ضرب و شتم قرار دادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000788941.mp3"},{"sentence":"There is now widespread support for these proposals, according to a recent public opinion poll.","translation":"بر اساس یک نظرسنجی اخیر، اکنون حمایت گسترده ای از این پیشنهادها وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841123.mp3"}]'::jsonb,2),
('bd03dbb5-6d89-5675-8773-5295e594e264','fd0c3deb-3ef7-5cf8-91d9-d9edf47cc6cb',2,null,null,'spoken & written','in a way that depends on differences in situations or amounts',null,null,'به گونه ای که به تفاوت در موقعیت ها یا مقادیر بستگی دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You will be paid according to the amount of work you do.","translation":"با توجه به میزان کاری که انجام می دهید به شما دستمزد پرداخت می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000788946.mp3"}]'::jsonb,1),
('4a195c72-3d54-5f2d-9e19-def8c22a2acb','fd0c3deb-3ef7-5cf8-91d9-d9edf47cc6cb',3,null,null,'spoken & written','in a way that agrees with a system or plan, or obeys a set of rules',null,null,'به گونه ای که با یک سیستم یا طرح موافق باشد یا از مجموعه ای از قوانین پیروی کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The game will be played according to rules laid down for the 1992 Cup.","translation":"این بازی طبق قوانین تعیین شده برای جام 1992 انجام خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841127.mp3"},{"sentence":"Everything went according to plan , and we arrived on time.","translation":"همه چیز طبق برنامه پیش رفت و به موقع رسیدیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841128.mp3"}]'::jsonb,2),
('308390a2-0808-5cb9-8b56-eabc14c260d1','f89b6ca0-ef2e-5b57-a11c-9491b1c7f119',1,null,null,'spoken & written','an important or official statement','[ countable ]',null,'اعلان، اعلامیه؛ اطلاعیه','{}'::text[],'{}'::text[],array['make/issue an announcement The next day an announcement was issued to staff, saying the company would be closing. The government issued an announcement saying that it was not prepared to negotiate with terrorists.','hear an announcement Everyone was shocked when they heard the announcement.','welcome an announcement (= say that you are pleased about it ) Environmental groups welcomed the announcement.','greet an announcement formal (= react to it in a particular way ) The announcement was. greeted with cheers on both sides of the House.','an announcement comes (= it happens ) His announcement came after two days of peace talks.','a formal announcement A formal announcement will be made in Parliament.','an official announcement No official announcement is expected until next year.','a surprise announcement/an unexpected announcement The Senator made the surprise announcement that he will not be seeking re-election.','a dramatic announcement (= sudden and important ) The dramatic announcement came after a cabinet meeting on Tuesday.','a further announcement A further announcement will be made in the near future.']::text[],'[{"sentence":"The minister made the announcement at a news conference.","translation":"وزیر کشور در یک کنفرانس خبری این خبر را اعلام کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000071.mp3"},{"sentence":"an important announcement about tax increases","translation":"یک اطلاعیه مهم در مورد افزایش مالیات","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000941076.mp3"},{"sentence":"They heard the announcement that the mayor was resigning.","translation":"آنها خبر استعفای شهردار را شنیدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000072.mp3"}]'::jsonb,3),
