('1eede29c-7081-5ee8-b040-a0cfffe5df87','2064f51b-64bf-54ff-8deb-05f9b1c9ca0c',1,null,null,'spoken & written','fairly large, especially large enough to have an effect or be important',null,null,'قابل‌توجه، چشمگیر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We’ve saved a considerable amount of money.","translation":"ما مقدار قابل توجهی پول پس انداز کرده ایم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001675284.mp3"},{"sentence":"Michael has already spent considerable time in Barcelona.","translation":"مایکل در حال حاضر زمان قابل توجهی را در بارسلونا گذرانده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001675285.mp3"},{"sentence":"issues of considerable importance","translation":"مسائل از اهمیت قابل توجهی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000856302.mp3"},{"sentence":"The series has aroused considerable interest.","translation":"این سریال علاقه قابل توجهی را برانگیخته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000856303.mp3"}]'::jsonb,4),
('0111f005-c774-57d6-959e-ab6aa4e80cf9','4fe2373e-33f1-5547-93f5-f459784e3fa7',1,null,null,'spoken & written','much or a lot',null,null,'به‌طور قابل‌توجه، به‌نحو چشمگیر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s considerably colder today.","translation":"امروز هوا خیلی سردتره","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000856321.mp3"},{"sentence":"Conditions have improved considerably over the past few years.","translation":"طی چند سال گذشته شرایط به طور قابل توجهی بهبود یافته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001675286.mp3"}]'::jsonb,2),
('238f944c-9356-5ae0-8021-1f4f661d605d','3f73ac96-073f-549e-a42d-351525c02f7d',1,'building something','ساختن چیزی','spoken & written','the process of building things such as houses, bridges , roads etc','[ uncountable ]',null,'ساخت، احداث؛ صنعت ساختمان','{}'::text[],'{}'::text[],array['the construction industry The construction industry had a hard time during the recession.','a construction company/firm It’s the largest construction company in Mexico.','a construction worker Thousands of construction workers are out of work.','construction work Construction work on the new road is expected to take two years.','a construction site (= an area where something is being built ) Safety is very important on a construction site.','a construction project/programme There are always a lot of large construction projects in Dubai.','construction materials expensive construction materials like cement and steel','construction costs The total construction costs will reach £125 million.','be under construction (= be being built ) A new road is currently under construction.','begin/start construction Developers are planning to begin construction on a new housing project.','complete construction We expect to complete construction in January.']::text[],'[{"sentence":"the construction of a new airport","translation":"ساخت فرودگاه جدید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668283.mp3"},{"sentence":"The hotel is currently under construction.","translation":"این هتل در حال حاضر در حال ساخت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668287.mp3"},{"sentence":"a road construction project","translation":"یک پروژه راهسازی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001790174.mp3"},{"sentence":"construction workers","translation":"کارگران ساختمانی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668288.mp3"}]'::jsonb,4),
