('8836b616-897a-5f6e-8a18-2f162d32b085','bc6a79f7-2840-5585-80a6-c6d88d423e10',1,null,null,'spoken & written','a conventional method , product , practice etc has been used for a long time and is considered the usual type','[ only before noun ]',null,'رایج، مرسوم؛ (نظریه) سنتی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Internet connections through conventional phone lines are fairly slow.","translation":"اتصال به اینترنت از طریق خطوط تلفن معمولی نسبتاً کند است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000861136.mp3"},{"sentence":"Bake for 20 minutes in a conventional oven; 8 in a microwave.","translation":"به مدت 20 دقیقه در فر معمولی بپزید؛ 8 در مایکروویو.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747334.mp3"}]'::jsonb,2),
