('44207843-eeee-5fb3-90cc-85d49fc65a61','a0137ee2-cf77-570f-83b1-ea307f3beed8',1,null,null,'spoken & written','an informal talk in which people exchange news , feelings , and thoughts','[ countable, uncountable ]',null,'گفت‌وگو، گفتار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a telephone conversation","translation":"یک مکالمه تلفنی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001109576.mp3"},{"sentence":"Children quickly get bored by adult conversation.","translation":"کودکان به سرعت از مکالمه بزرگسالان خسته می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747593.mp3"},{"sentence":"a short conversation with the teacher","translation":"گفتگوی کوتاه با معلم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747596.mp3"},{"sentence":"a conversation about family and friends","translation":"گفتگو در مورد خانواده و دوستان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747599.mp3"},{"sentence":"They had a short conversation in German and seemed to be disagreeing about something.","translation":"آنها مکالمه کوتاهی به آلمانی داشتند و به نظر می رسید در مورد چیزی اختلاف نظر دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001109580.mp3"},{"sentence":"It’s impossible to carry on a conversation with all this noise in the background.","translation":"ادامه گفتگو با این همه سروصدا در پس زمینه غیرممکن است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001109584.mp3"},{"sentence":"‘Did you have a good journey?’ he said, trying to make conversation .","translation":"او در حالی که سعی داشت مکالمه کند گفت: \"سفر خوبی داشتی؟\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747628.mp3"},{"sentence":"He was silent, no matter how hard Sofia tried to engage him in conversation .","translation":"او ساکت بود، مهم نیست که صوفیا چقدر سعی کرد او را درگیر گفتگو کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001845499.mp3"},{"sentence":"After a while, the conversation turned to a friend’s coming wedding.","translation":"پس از مدتی، گفتگو به عروسی آینده یکی از دوستان تبدیل شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001109588.mp3"},{"sentence":"They were deep in conversation , relaxed and smiling.","translation":"آنها عمیقاً در گفتگو بودند، آرام و خندان بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001109602.mp3"},{"sentence":"He could hear snatches of conversation from across the room.","translation":"او می‌توانست صدای مکالمه را از آن طرف اتاق بشنود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747613.mp3"}]'::jsonb,11),
