('c6a042be-b208-5c52-8c77-b08353576564','53f0de4a-b48e-5a82-bd2a-8dd4b5c2f1cf',1,null,null,'spoken & written','unhappy because something you hoped for did not happen, or because someone or something was not as good as you expected',null,null,'ناامید، مایوس؛ بی‌قرار (از نتیجه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Dad seemed more disappointed than angry.","translation":"پدر بیشتر ناامید به نظر می رسید تا عصبانی.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000826904.mp3"},{"sentence":"disappointed customers","translation":"مشتریان ناامید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001703778.mp3"},{"sentence":"I was disappointed that we played so well yet still lost.","translation":"از اینکه اینقدر خوب بازی کردیم اما باز هم شکست خوردیم ناامید شدم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000826913.mp3"},{"sentence":"Local residents were disappointed with the decision.","translation":"ساکنان محلی از این تصمیم ناامید شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000826919.mp3"},{"sentence":"People are disappointed by the lack of political change.","translation":"مردم از عدم تغییر سیاسی ناامید شده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00281.mp3"},{"sentence":"I’m very disappointed in you.","translation":"من از شما بسیار ناامید هستم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000826910.mp3"},{"sentence":"Visitors were disappointed to find the museum closed.","translation":"بازدیدکنندگان از بسته شدن موزه ناامید شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000826922.mp3"},{"sentence":"The girl’s parents were bitterly disappointed at the jury’s verdict.","translation":"والدین دختر به شدت از رای هیئت منصفه ناامید شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000826925.mp3"}]'::jsonb,8),
