('20cb38f2-9b8c-5c17-bb64-0f807ce3378d','4bc07779-ec11-5712-87ad-4a461f46c179',1,null,null,'spoken & written','an official attempt to find out the truth about or the cause of something such as a crime , accident , or scientific problem','[ countable ]',null,'تحقیق، بررسی؛ رسیدگی (رسمی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The investigation continued for nearly three years.","translation":"تحقیقات نزدیک به سه سال ادامه داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724295.mp3"},{"sentence":"The authorities are planning to launch a full-scale investigation into the crash.","translation":"مقامات در حال برنامه ریزی برای آغاز تحقیقات کامل در مورد سقوط هواپیما هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724296.mp3"},{"sentence":"Baker demanded an investigation of the district attorney’s office.","translation":"بیکر خواستار تحقیق از دفتر دادستان منطقه شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724299.mp3"},{"sentence":"a criminal investigation","translation":"تحقیقات جنایی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724300.mp3"},{"sentence":"A private detective was hired to conduct the investigation .","translation":"یک کارآگاه خصوصی برای انجام تحقیقات استخدام شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724303.mp3"}]'::jsonb,5),
