('28a3f841-c6e2-5561-87f2-e95ba9c1182e','9aeb10ca-a6b6-57de-9adc-bd201a6d659b',2,null,null,'spoken & written','relating to what is in someone’s mind rather than what is real',null,null,'مربوط به آنچه در ذهن کسی است نه آنچه واقعی است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Max says he’s ill, but I’m sure it’s psychological.","translation":"مکس می گوید که او بیمار است، اما من مطمئن هستم که این موضوع روانی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000269540.mp3"}]'::jsonb,1),
