('9595b6a6-b192-5c05-8a79-f6120de52c89','2f15087a-f9eb-5d2d-9e92-978547004664',1,null,null,'spoken & written','sympathetic and kind about other people’s problems',null,null,'نسبت به مشکلات دیگران دلسوز و مهربان است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Luckily, I have a very understanding boss.","translation":"خوشبختانه من رئیس بسیار فهمیده ای دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000548150.mp3"}]'::jsonb,1),
('57f3a0b1-5d9d-58a4-b4f7-49a5dfe58211','483d45cc-1d87-53bb-9eee-05423d829a67',1,null,null,'spoken & written','used when you are mentioning a fact that you wish was not true',null,null,'متأسفانه، افسوس که؛ متأسفانه (تأکید)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Unfortunately, you were out when we called.","translation":"متأسفانه وقتی تماس گرفتیم بیرون بودید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000549686.mp3"}]'::jsonb,1),
('d71d6f79-1d89-5e26-95bc-4b005a6b3984','2727f3be-495d-5a7b-af88-699b32b5c2e9',1,null,null,'spoken & written','the activities that are involved in managing the work of a company or organization','[ uncountable ]',null,'مدیریت، امور اداری؛ دولت، هیئت حاکمه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We’re looking for someone with experience in administration.","translation":"به دنبال یک نفر با تجربه در مدیریت هستیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000792809.mp3"},{"sentence":"The health service spends too much on administration.","translation":"خدمات بهداشتی و درمانی بیش از حد برای مدیریت هزینه می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000792810.mp3"},{"sentence":"the college administration","translation":"مدیریت کالج","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001609506.mp3"}]'::jsonb,3),
('e3fc257b-9e28-5ae7-a7d2-d4c184944653','2727f3be-495d-5a7b-af88-699b32b5c2e9',2,null,null,'spoken & written','the government of a country at a particular time','[ countable ]',null,'حکومت یک کشور در یک زمان خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the Kennedy Administration","translation":"دولت کندی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000792822.mp3"},{"sentence":"The problem has been ignored by successive administrations.","translation":"این مشکل توسط دولت های متوالی نادیده گرفته شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000792823.mp3"}]'::jsonb,2),
('acdca453-3ffe-5040-b855-7fd0ad2700a7','2727f3be-495d-5a7b-af88-699b32b5c2e9',3,null,null,'spoken & written','the act of administering something, especially a law , test , or medicine','[ uncountable ]',null,'عمل انجام دادن چیزی، به ویژه قانون، آزمایش یا دارو','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the administration of justice","translation":"اجرای عدالت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000792828.mp3"},{"sentence":"the administration of sedatives","translation":"تجویز داروهای آرام بخش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001609507.mp3"}]'::jsonb,2),
('9ad3f451-8002-5a1e-9c17-2a882a02e19f','a7621c88-c634-5c97-9285-0b62b3c7c050',1,null,null,'spoken & written','relating to the work of managing a company or organization',null,null,'اداری، اجرایی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The job is mainly administrative.","translation":"کار عمدتا اداری است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000792839.mp3"},{"sentence":"the administrative costs of health care systems","translation":"هزینه های اداری سیستم های مراقبت های بهداشتی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776552.mp3"},{"sentence":"an administrative assistant","translation":"یک دستیار اداری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001609510.mp3"},{"sentence":"staff who provide technical and administrative support to the college","translation":"کارکنانی که از دانشکده پشتیبانی فنی و اداری می کنند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776556.mp3"}]'::jsonb,4),
('bde82c89-6980-57fb-9741-a7eddbb5e677','4d4d4856-9b69-506b-9180-b030b164a4cf',1,null,null,'spoken & written','a quality or feature of something or someone that is typical of them and easy to recognize',null,null,'ویژگی، مشخصه، خصیصه','{}'::text[],'{}'::text[],array['a physical characteristic physical characteristics such as your height and weight','a personal characteristic (= relating to someone’s character ) What are the personal characteristics that a leader requires?','a human characteristic The power of speech is an entirely human characteristic.','a national characteristic (= typical of the people of a country ) Organization is often seen as a German national characteristic.','the main characteristic of something A new interest in art was one of the main characteristics of this period.','a common characteristic (= that people or things share ) Successful firms tend to have common characteristics.','a distinguishing/distinctive characteristic (= separating someone or something from others of the same type ) The blue feathers are the distinguishing characteristic of the male bird.','a defining characteristic (= one that is necessary in order to be a particular type of person or thing ) Originality is one of the defining characteristics of a great band.','an important/essential characteristic An essential characteristic of good teaching is that it must create interest in the learner.','an inherited characteristic Intelligence is an inherited characteristic.','a striking characteristic Its canals are one of Amsterdam’s most striking characteristics.','have a characteristic ( also possess a characteristic formal ) He has all the characteristics of a great husband.','show a characteristic ( also exhibit a characteristic formal ) A material may exhibit the characteristics of both a liquid and a solid.','share a characteristic The group shared one characteristic - they were all under 25.','inherit a characteristic (= get a characteristic from your parent ) We all inherit physical characteristics from our parents.']::text[],'[{"sentence":"a baby discovering the physical characteristics of objects","translation":"کودکی که ویژگی های فیزیکی اشیاء را کشف می کند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000880366.mp3"},{"sentence":"Violent images are a defining characteristic of his work.","translation":"تصاویر خشونت آمیز ویژگی بارز آثار او هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000880365.mp3"}]'::jsonb,2),
('fa39f370-88cb-575b-bd07-ece20c62aa4e','c81f324c-74db-58f1-9d74-511b10de6df9',1,null,null,'spoken & written','very typical of a particular thing or of someone’s character',null,null,'بسیار معمولی برای یک چیز خاص یا شخصیت کسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the highly characteristic (= very typical ) flint walls of the local houses","translation":"دیوارهای سنگ چخماق بسیار مشخص (= بسیار معمولی) خانه های محلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000880375.mp3"},{"sentence":"the qualities that were characteristic of the Nixon administration","translation":"ویژگی هایی که مشخصه دولت نیکسون بود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000880378.mp3"}]'::jsonb,2),
('265c58c9-d25b-51ef-9776-89a57e1743b8','ff87e19d-995e-5ce8-a5e9-d5ca774c3651',1,null,null,'spoken & written',null,null,'congratulations','تبریک، تهنیت','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('35c52a17-6be5-5fac-a380-d1b7c21894fe','ff87e19d-995e-5ce8-a5e9-d5ca774c3651',2,null,null,'spoken & written','when you tell someone that you are happy because they have achieved something or because something nice has happened to them','[ uncountable ]',null,'وقتی به کسی می گویید که خوشحال هستید زیرا او به چیزی دست یافته یا اتفاق خوبی برای او افتاده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"letters of congratulation","translation":"نامه های تبریک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001965615.mp3"}]'::jsonb,1),
('2061787d-8c57-5a67-b2c1-22bf4e2ef7e9','bbbef3b0-ddff-573c-b885-299d0909ae36',1,null,null,'spoken & written','the way in which someone explains or understands an event , information, someone’s actions etc',null,null,'تفسیر، برداشت؛ ترجمه شفاهی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"One possible interpretation is that they want you to resign.","translation":"یک تعبیر احتمالی این است که آنها از شما می خواهند استعفا دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001421877.mp3"},{"sentence":"It’s difficult to put an accurate interpretation on (= explain ) the survey results.","translation":"ارائه تفسیر دقیق (= توضیح) نتایج نظرسنجی دشوار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001421881.mp3"},{"sentence":"What exactly the author meant by that statement is open to interpretation (= able to be understood or explained in different ways ) .","translation":"منظور نویسنده از آن بیانیه دقیقاً قابل تفسیر است (= قابل درک یا توضیح به طرق مختلف).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721752.mp3"}]'::jsonb,3),
('aa68e29a-6202-50ce-a676-6550931a92ad','bbbef3b0-ddff-573c-b885-299d0909ae36',2,null,null,'spoken & written','the way in which someone performs a play, a piece of music etc and shows what they think and feel about it',null,null,'روشی که در آن شخصی یک نمایشنامه، یک قطعه موسیقی و غیره را اجرا می کند و نشان می دهد که در مورد آن چه فکر و احساسی دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Laurence Olivier’s brilliant interpretation of Henry V","translation":"تفسیر درخشان لارنس اولیویه از هنری پنجم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001421886.mp3"}]'::jsonb,1),
('390557ff-e1f5-5c05-b798-2ef2bad0d2c2','4ae67f1a-eb79-5c91-9ec9-59846390ab8b',1,null,null,'spoken & written','official advice given to someone, especially about what to do','[ countable ]',null,'توصیه، پیشنهاد (رسمی)؛ توصیه‌نامه؛ پیشنهاد (پرداخت)','{}'::text[],'{}'::text[],array['make a recommendation The inspectors will make their recommendations to the Environment Secretary.','accept a recommendation The president accepted the report’s recommendations.','approve/adopt a recommendation The council approved the committee’s recommendation.','implement recommendations We will implement the recommendations of the Woolf Report to improve prison conditions.','the main recommendation One of the main recommendations in the report is more parental involvement in education.','specific/detailed recommendations We made a large number of specific recommendations for improving women’s mental health.','a clear recommendation The report offered no clear recommendations or policy guidelines.']::text[],'[{"sentence":"We will review the case and make a recommendation to the client.","translation":"ما پرونده را بررسی می کنیم و به مشتری توصیه می کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001614064.mp3"},{"sentence":"recommendations for school reform","translation":"توصیه هایی برای اصلاح مدارس","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001303.mp3"},{"sentence":"the main recommendations of the report","translation":"توصیه های اصلی گزارش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001876447.mp3"},{"sentence":"We are making no recommendation that children should use Standard English.","translation":"ما هیچ توصیه ای برای استفاده کودکان از انگلیسی استاندارد نداریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001614073.mp3"},{"sentence":"a recommendation to replace the existing system","translation":"پیشنهادی برای جایگزینی سیستم موجود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001614076.mp3"}]'::jsonb,5),
('c7756b42-26fa-5019-83e9-d9a9ab387722','4ae67f1a-eb79-5c91-9ec9-59846390ab8b',2,null,null,'spoken & written','a suggestion to someone that they should choose a particular thing or person that you think is very good','[ uncountable ]',null,'پیشنهادی به کسی که باید چیز یا شخص خاصی را انتخاب کند که به نظر شما خیلی خوب است','{}'::text[],'{}'::text[],array['make a recommendation The inspectors will make their recommendations to the Environment Secretary.','accept a recommendation The president accepted the report’s recommendations.','approve/adopt a recommendation The council approved the committee’s recommendation.','implement recommendations We will implement the recommendations of the Woolf Report to improve prison conditions.','the main recommendation One of the main recommendations in the report is more parental involvement in education.','specific/detailed recommendations We made a large number of specific recommendations for improving women’s mental health.','a clear recommendation The report offered no clear recommendations or policy guidelines.']::text[],'[{"sentence":"Academic staff are appointed on the recommendation of a committee.","translation":"کارکنان دانشگاهی به پیشنهاد یک کمیته منصوب می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001771368.mp3"}]'::jsonb,1),
('c7f9b4c7-285e-53d7-b77d-54b21a47d9c4','4ae67f1a-eb79-5c91-9ec9-59846390ab8b',3,null,null,'spoken & written','a formal letter or statement saying that someone would be a suitable person to do a job, take a course of study etc','[ countable ]',null,'نامه یا بیانیه رسمی مبنی بر اینکه شخصی برای انجام یک کار، گذراندن دوره تحصیلی و غیره فرد مناسبی است','{}'::text[],'{}'::text[],array['make a recommendation The inspectors will make their recommendations to the Environment Secretary.','accept a recommendation The president accepted the report’s recommendations.','approve/adopt a recommendation The council approved the committee’s recommendation.','implement recommendations We will implement the recommendations of the Woolf Report to improve prison conditions.','the main recommendation One of the main recommendations in the report is more parental involvement in education.','specific/detailed recommendations We made a large number of specific recommendations for improving women’s mental health.','a clear recommendation The report offered no clear recommendations or policy guidelines.']::text[],'[{"sentence":"Try to get letters of recommendation from bosses and colleagues.","translation":"سعی کنید از روسا و همکاران توصیه نامه دریافت کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001304.mp3"}]'::jsonb,1)
